SELECT jsonb_build_object(
'column_defaults',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'identity',a.attidentity,'expression',pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attnum) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped AND (d.oid IS NOT NULL OR a.attidentity<>'')),
'sequence_dependencies',(SELECT coalesce(jsonb_agg(jsonb_build_object('dependent',pg_describe_object(d.classid,d.objid,d.objsubid),'referenced',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid),'type',d.deptype)),'[]'::jsonb) FROM pg_depend d WHERE d.objid='public.road_network_edges_edge_id_seq'::regclass OR (d.refclassid='pg_class'::regclass AND d.refobjid='public.road_network_edges_edge_id_seq'::regclass)),
'other_public_relations',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'owner',c.relowner::regrole::text)),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m','f'))
) AS dependencies;
